package com.smartbanksorter;

import java.util.Arrays;
import java.util.List;

/**
 * Built-in category names, in their default display order.
 */
final class Categories
{
	static final String CURRENCY = "Currency";
	static final String MELEE = "Melee";
	static final String RANGED = "Ranged";
	static final String MAGIC = "Magic";
	static final String SLAYER = "Slayer";
	static final String JEWELLERY = "Jewellery";
	static final String AMMO = "Ammo";
	static final String RUNES = "Runes";
	static final String TELEPORTS = "Teleports";
	static final String POTIONS = "Potions";
	static final String FOOD = "Food";
	static final String PRAYER = "Prayer";
	static final String TOOLS = "Tools";
	static final String HERBLORE = "Herblore";
	static final String FARMING = "Farming";
	// Materials go to the skill that uses them.
	static final String ORES_BARS = "Smithing";
	static final String GEMS = "Crafting";
	static final String LOGS_PLANKS = "Fletching";
	static final String CLUES = "Clues";
	static final String QUEST = "Quest";
	static final String COSMETIC = "Cosmetic";
	static final String OTHER_GEAR = "Other gear";
	static final String MISC = "Misc";

	static final List<String> SKILLS = Arrays.asList(
		"Mining", "Smithing", "Fishing", "Cooking", "Woodcutting", "Firemaking", "Fletching", "Crafting",
		HERBLORE, FARMING, "Hunter", "Construction", "Agility", "Thieving", "Runecraft", "Sailing"
	);

	static final List<String> DEFAULT_ORDER = Arrays.asList(
		CURRENCY, MELEE, RANGED, MAGIC, SLAYER, AMMO, RUNES, TELEPORTS, POTIONS, FOOD, PRAYER,
		"Mining", "Smithing", "Fishing", "Cooking", "Woodcutting", "Firemaking", "Fletching", "Crafting",
		HERBLORE, FARMING, "Hunter", "Construction", "Agility", "Thieving", "Runecraft", "Sailing",
		// Jewellery left here has no combat or teleport use (those go to the styles / Teleports).
		TOOLS, CLUES, QUEST, JEWELLERY, COSMETIC, OTHER_GEAR, MISC
	);

	private Categories()
	{
	}
}

package com.smartbanksorter;

import static com.smartbanksorter.Categories.*;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.client.game.ItemEquipmentStats;

/**
 * Decides an item's category. Equipment is classified from its combat stats rather than its name,
 * everything else from its inventory actions (Eat, Drink, Bury, Break...) and then a few name rules.
 */
final class Categoriser
{
	private static final Set<String> TOOLS_EXACT = new HashSet<>(Arrays.asList(
		"hammer", "chisel", "knife", "tinderbox", "needle", "saw", "crystal saw", "spade", "rake",
		"seed dibber", "secateurs", "magic secateurs", "gardening trowel", "small fishing net",
		"big fishing net", "fishing rod", "fly fishing rod", "oily fishing rod", "lobster pot",
		"karambwan vessel", "glassblowing pipe", "pestle and mortar", "machete", "imcando hammer",
		"ammo mould", "amulet mould", "ring mould", "necklace mould", "bracelet mould", "tiara mould",
		"holy mould", "sickle mould", "bolt mould", "unholy mould", "bucket", "empty bucket", "pot",
		"jug", "shears", "noose wand", "butterfly net", "bird snare", "box trap", "rabbit snare",
		"teasing stick", "rope"
	));
	private static final String[] TOOL_SUFFIXES = {
		" pickaxe", " axe", " felling axe", " harpoon", " hammer", " saw", " chisel"
	};
	private static final Set<String> CLEAN_HERBS = new HashSet<>(Arrays.asList(
		"guam leaf", "marrentill", "tarromin", "harralander", "ranarr weed", "toadflax", "irit leaf",
		"avantoe", "kwuarm", "huasca", "snapdragon", "cadantine", "lantadyme", "dwarf weed", "torstol"
	));
	private static final Set<String> GEMS_EXACT = new HashSet<>(Arrays.asList(
		"opal", "jade", "red topaz", "sapphire", "emerald", "ruby", "diamond", "dragonstone", "onyx",
		"zenyte"
	));

	private static final Set<String> COMBAT_STYLES = new HashSet<>(Arrays.asList(MELEE, RANGED, MAGIC));
	private static final UserRules OVERRIDES = UserRules.parse(readResource("overrides.txt"));

	private final UserRules userRules;

	Categoriser(UserRules userRules)
	{
		this.userRules = userRules;
	}

	/**
	 * @param equipment combat stats, or null if the item is not equipable
	 */
	String categorise(int itemId, String name, String[] actions, ItemEquipmentStats equipment)
	{
		String custom = userRules.match(itemId, name);
		if (custom == null)
		{
			custom = OVERRIDES.match(itemId, name);
		}
		if (custom == null)
		{
			ItemData.Entry data = ItemData.get(name);
			custom = data == null ? null : data.category;
			// For combat gear the item's own stats decide the style; the data only moves gear out of the styles
			// (Slayer, a skill, Cosmetic...).
			if (custom != null && equipment != null && COMBAT_STYLES.contains(custom))
			{
				String byStats = gear(name.toLowerCase(), equipment);
				if (COMBAT_STYLES.contains(byStats))
				{
					custom = byStats;
				}
			}
		}
		return custom != null ? custom : builtIn(name.toLowerCase(), actions, equipment);
	}

	static String builtIn(String name, String[] actions, ItemEquipmentStats equipment)
	{
		if (name.equals("coins") || name.equals("platinum token"))
		{
			return CURRENCY;
		}
		// Before equipment: many tools are wieldable and would otherwise land in Melee.
		if (isTool(name))
		{
			return TOOLS;
		}
		// Charged teleport jewellery (glory, games necklace, dueling, wealth, combat bracelet...) is rubbed to
		// teleport; uncharged versions can't be, so they stay with gear. Xeric's talisman works the same way.
		if (hasAction(actions, "Rub") && (equipment != null || name.contains("talisman")))
		{
			return TELEPORTS;
		}
		if (equipment != null)
		{
			return gear(name, equipment);
		}
		// Dwarf multicannon parts and cannonballs.
		if (name.contains("cannon"))
		{
			return RANGED;
		}
		if (hasAction(actions, "Eat"))
		{
			return FOOD;
		}
		if (hasAction(actions, "Drink"))
		{
			return POTIONS;
		}
		if (hasAction(actions, "Bury") || hasAction(actions, "Scatter") || name.startsWith("ensouled "))
		{
			return PRAYER;
		}
		// Blighted spell sacks (ice barrage, entangle, vengeance, teleblock...) are spell supplies.
		if (name.startsWith("blighted ") && name.endsWith(" sack"))
		{
			return RUNES;
		}
		if (hasAction(actions, "Break") || name.contains("teleport") || name.equals("royal seed pod"))
		{
			return TELEPORTS;
		}
		if (name.endsWith(" rune") || name.contains("rune pouch"))
		{
			return RUNES;
		}
		// Crystal armour/weapon/tool seeds are Prifddinas crafting materials, not farming seeds.
		if ((name.contains("seed") && !name.contains("crystal ")) || name.contains("sapling") || name.contains("compost"))
		{
			return FARMING;
		}
		if (name.startsWith("grimy ") || name.endsWith("(unf)") || CLEAN_HERBS.contains(name)
			|| name.startsWith("vial of ") || name.equals("vial"))
		{
			return HERBLORE;
		}
		if (name.startsWith("uncut ") || GEMS_EXACT.contains(name))
		{
			return GEMS;
		}
		if (name.endsWith(" ore") || name.endsWith(" bar") || name.equals("coal"))
		{
			return ORES_BARS;
		}
		if (name.endsWith("logs") || name.endsWith("plank"))
		{
			return LOGS_PLANKS;
		}
		if (name.startsWith("clue scroll") || name.startsWith("reward casket") || name.startsWith("clue bottle")
			|| name.startsWith("clue geode") || name.startsWith("clue nest") || name.startsWith("scroll box"))
		{
			return CLUES;
		}
		return MISC;
	}

	static String gear(String name, ItemEquipmentStats e)
	{
		int slot = e.getSlot();
		if (slot == EquipmentInventorySlot.AMMO.getSlotIdx())
		{
			// God blessings use the ammo slot but suit every style; they live with Melee and get copies elsewhere.
			return name.contains("blessing") ? MELEE : AMMO;
		}

		int meleeAttack = Math.max(e.getAstab(), Math.max(e.getAslash(), e.getAcrush()));
		if (slot == EquipmentInventorySlot.WEAPON.getSlotIdx())
		{
			// Staves carry crush bonuses too, so any real magic bonus wins.
			if (e.getAmagic() >= 10 || e.getMdmg() > 0)
			{
				return MAGIC;
			}
			if (e.getArange() > 0 && e.getArange() >= meleeAttack)
			{
				return RANGED;
			}
			if (meleeAttack > 0 || e.getStr() > 0)
			{
				return MELEE;
			}
			return e.getAmagic() > 0 ? MAGIC : OTHER_GEAR;
		}

		// Armour: pick the style with the highest offensive contribution.
		int melee = Math.max(meleeAttack, 0) + e.getStr();
		int ranged = Math.max(e.getArange(), 0) + e.getRstr();
		int magic = Math.max(e.getAmagic(), 0) + Math.round(e.getMdmg());
		if (melee > 0 && melee >= ranged && melee >= magic)
		{
			return MELEE;
		}
		if (ranged > 0 && ranged >= magic)
		{
			return RANGED;
		}
		if (magic > 0)
		{
			return MAGIC;
		}

		// Amulets and rings without combat bonuses: teleport jewellery, ring of suffering, etc.
		if (slot == EquipmentInventorySlot.AMULET.getSlotIdx() || slot == EquipmentInventorySlot.RING.getSlotIdx())
		{
			return JEWELLERY;
		}

		// No offensive stats: plain defensive armour (plate, shields) is tank/melee gear.
		boolean defensive = e.getDstab() > 0 || e.getDslash() > 0 || e.getDcrush() > 0
			|| e.getDmagic() > 0 || e.getDrange() > 0;
		return defensive ? MELEE : OTHER_GEAR;
	}

	private static String readResource(String name)
	{
		try (InputStream in = Categoriser.class.getResourceAsStream(name))
		{
			return in == null ? "" : new String(in.readAllBytes(), StandardCharsets.UTF_8);
		}
		catch (IOException e)
		{
			return "";
		}
	}

	static boolean isTool(String name)
	{
		if (TOOLS_EXACT.contains(name) || name.startsWith("watering can"))
		{
			return true;
		}
		for (String suffix : TOOL_SUFFIXES)
		{
			if (name.endsWith(suffix))
			{
				return true;
			}
		}
		return false;
	}

	private static boolean hasAction(String[] actions, String action)
	{
		if (actions != null)
		{
			for (String a : actions)
			{
				if (action.equalsIgnoreCase(a))
				{
					return true;
				}
			}
		}
		return false;
	}
}

package com.smartbanksorter;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeSet;
import java.util.function.Function;
import java.util.function.ToIntFunction;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Layouts for Food (best heal first, combo food on its own rows) and Potions (one column per potion,
 * doses going down, combat potions first).
 */
final class ConsumableOrder
{
	private static final Pattern DOSE = Pattern.compile("^(.*?)\\s*\\((\\d+)\\)$");
	// Foods that can be eaten on the same tick as normal food.
	private static final List<String> COMBO_FOOD = Arrays.asList(
		"karambwan", "halibut", "batta", "crunchies", "chocolate bomb", "toad's legs", "worm hole", "veg ball", "tangled toad"
	);
	// Potion families in display order; matched by "name contains", most specific first. Raid essentials lead
	// (divine super combat, divine ranging, brews, restores), then other combat boosts, prayer, cures, utility.
	private static final List<String> POTION_ORDER = Arrays.asList(
		"divine super combat", "divine ranging", "saradomin brew", "super restore",
		"super combat", "ranging", "divine bastion", "bastion", "divine magic", "magic potion",
		"divine battlemage", "battlemage", "divine super attack", "super attack", "divine super strength",
		"super strength", "divine super defence", "super defence",
		"prayer potion", "prayer regeneration", "sanfew", "zamorak brew",
		"anti-venom+", "anti-venom", "antidote++", "antidote+", "superantipoison", "antipoison",
		"extended super antifire", "super antifire", "extended antifire", "antifire",
		"stamina", "super energy", "energy potion", "attack potion", "strength potion", "defence potion"
	);

	private ConsumableOrder()
	{
	}

	static <T> List<List<T>> food(List<T> items, Function<T, String> name, ToIntFunction<T> heal,
		Comparator<T> tiebreak)
	{
		List<T> normal = new ArrayList<>();
		List<T> combo = new ArrayList<>();
		for (T item : items)
		{
			(isCombo(name.apply(item)) ? combo : normal).add(item);
		}
		Comparator<T> order = Comparator.comparingInt(heal).reversed().thenComparing(tiebreak);
		normal.sort(order);
		combo.sort(order);

		List<List<T>> rows = new ArrayList<>();
		if (!normal.isEmpty())
		{
			rows.add(normal);
		}
		if (!combo.isEmpty())
		{
			rows.add(combo);
		}
		return rows;
	}

	static boolean isCombo(String name)
	{
		String n = name.toLowerCase();
		return COMBO_FOOD.stream().anyMatch(n::contains);
	}

	/**
	 * @return rows of cells; each block of up to {@code columns} potions has one row per dose, highest first,
	 * with null where a potion lacks that dose. Undosed drinks follow.
	 */
	static <T> List<List<T>> potions(List<T> items, Function<T, String> name, Comparator<T> tiebreak, int columns)
	{
		Map<String, Map<Integer, T>> families = new LinkedHashMap<>();
		List<T> loose = new ArrayList<>();
		List<T> sorted = new ArrayList<>(items);
		sorted.sort(tiebreak);
		for (T item : sorted)
		{
			Matcher m = DOSE.matcher(name.apply(item));
			if (!m.matches())
			{
				loose.add(item);
				continue;
			}
			Map<Integer, T> doses = families.computeIfAbsent(m.group(1).toLowerCase(), k -> new LinkedHashMap<>());
			// A second item with the same name and dose (rare) can't share the cell.
			if (doses.putIfAbsent(Integer.parseInt(m.group(2)), item) != null)
			{
				loose.add(item);
			}
		}

		List<String> order = new ArrayList<>(families.keySet());
		order.sort(Comparator.comparingInt(ConsumableOrder::potionRank).thenComparing(Comparator.naturalOrder()));

		List<List<T>> rows = new ArrayList<>();
		for (int first = 0; first < order.size(); first += columns)
		{
			List<String> block = order.subList(first, Math.min(first + columns, order.size()));
			TreeSet<Integer> doses = new TreeSet<>(Comparator.reverseOrder());
			block.forEach(f -> doses.addAll(families.get(f).keySet()));
			for (int dose : doses)
			{
				List<T> row = new ArrayList<>();
				for (String family : block)
				{
					row.add(families.get(family).get(dose));
				}
				while (!row.isEmpty() && row.get(row.size() - 1) == null)
				{
					row.remove(row.size() - 1);
				}
				rows.add(row);
			}
		}
		if (!loose.isEmpty())
		{
			rows.add(loose);
		}
		return rows;
	}

	static int potionRank(String family)
	{
		for (int i = 0; i < POTION_ORDER.size(); i++)
		{
			if (family.contains(POTION_ORDER.get(i)))
			{
				return i;
			}
		}
		return POTION_ORDER.size();
	}
}

package com.smartbanksorter;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import java.util.function.ToLongFunction;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.client.game.ItemEquipmentStats;

/**
 * Orders combat gear by how close it is to your best-in-slot. Weapons come first, best first. Armour is
 * ranked within its slot; tier 0 is your best piece for each slot, tier 1 the next best, and so on.
 * <p>
 * In column layout each tier is one bank column read head to feet, so the first column is your best
 * outfit. In row layout each tier is one row instead (shields then follow the weapons, to keep rows at 8).
 */
final class GearOrder
{
	// Head-to-feet order of an outfit column.
	private static final EquipmentInventorySlot[] COLUMN_ORDER = {
		EquipmentInventorySlot.HEAD, EquipmentInventorySlot.CAPE, EquipmentInventorySlot.AMULET,
		EquipmentInventorySlot.BODY, EquipmentInventorySlot.SHIELD, EquipmentInventorySlot.LEGS,
		EquipmentInventorySlot.GLOVES, EquipmentInventorySlot.BOOTS, EquipmentInventorySlot.RING,
	};
	// Head-to-feet order of an outfit row; exactly 8 slots, one bank row.
	private static final EquipmentInventorySlot[] ROW_ORDER = {
		EquipmentInventorySlot.HEAD, EquipmentInventorySlot.CAPE, EquipmentInventorySlot.AMULET,
		EquipmentInventorySlot.BODY, EquipmentInventorySlot.LEGS, EquipmentInventorySlot.GLOVES,
		EquipmentInventorySlot.BOOTS, EquipmentInventorySlot.RING,
	};
	// Row layout: once tiers get this sparse, stop starting new rows and pack the rest.
	private static final int MIN_ROW_ITEMS = 3;

	private GearOrder()
	{
	}

	/**
	 * @param price GE price per item; weapons are ranked by it because their stats miss special effects
	 * @param set the item's set-effect set name, or null
	 * @param columns lay outfits out as columns rather than rows
	 * @return rows of cells, each starting on a new bank row; null cells are left empty
	 */
	static <T> List<List<T>> order(List<T> items, String category, Function<T, ItemEquipmentStats> stats,
		ToLongFunction<T> price, Function<T, String> set, Comparator<T> tiebreak, boolean columns, int bankColumns)
	{
		Comparator<T> byStats = Comparator.comparingInt((T t) -> score(category, stats.apply(t))).reversed();
		Comparator<T> byPrice = Comparator.comparingLong(price).reversed();

		List<T> weapons = new ArrayList<>();
		List<T> blessings = new ArrayList<>();
		List<T> other = new ArrayList<>();
		Map<Integer, List<T>> bySlot = new HashMap<>();
		for (T item : items)
		{
			ItemEquipmentStats e = stats.apply(item);
			if (e == null)
			{
				other.add(item);
			}
			else if (e.getSlot() == EquipmentInventorySlot.WEAPON.getSlotIdx())
			{
				weapons.add(item);
			}
			else if (e.getSlot() == EquipmentInventorySlot.AMMO.getSlotIdx())
			{
				blessings.add(item);
			}
			else
			{
				bySlot.computeIfAbsent(e.getSlot(), k -> new ArrayList<>()).add(item);
			}
		}
		for (List<T> slotItems : bySlot.values())
		{
			slotItems.sort(byStats.thenComparing(byPrice).thenComparing(tiebreak));
		}

		List<List<T>> rows = new ArrayList<>();
		// Tradeable weapons by price, then untradeables (price 0) by stats.
		weapons.sort(byPrice.thenComparing(byStats).thenComparing(tiebreak));
		blessings.sort(byStats.thenComparing(byPrice).thenComparing(tiebreak));
		List<T> hands = new ArrayList<>(weapons);
		hands.addAll(blessings);
		if (!columns)
		{
			List<T> shields = bySlot.remove(EquipmentInventorySlot.SHIELD.getSlotIdx());
			if (shields != null)
			{
				hands.addAll(shields);
			}
		}
		if (!hands.isEmpty())
		{
			rows.add(hands);
		}

		EquipmentInventorySlot[] order = columns ? COLUMN_ORDER : ROW_ORDER;
		// Gear in slots outside an outfit (e.g. ammo moved here by a custom rule) goes at the end.
		for (Map.Entry<Integer, List<T>> entry : bySlot.entrySet())
		{
			if (!inOrder(order, entry.getKey()))
			{
				other.addAll(0, entry.getValue());
			}
		}
		Map<Integer, List<T>> grid = assignTiers(bySlot, order, set);
		int tiers = 0;
		for (List<T> slotColumn : grid.values())
		{
			tiers = Math.max(tiers, slotColumn.size());
		}

		if (columns)
		{
			// Blocks of up to bankColumns outfits side by side.
			for (int first = 0; first < tiers; first += bankColumns)
			{
				for (EquipmentInventorySlot slot : COLUMN_ORDER)
				{
					List<T> slotColumn = grid.getOrDefault(slot.getSlotIdx(), Collections.emptyList());
					List<T> row = new ArrayList<>();
					for (int tier = first; tier < first + bankColumns && tier < slotColumn.size(); tier++)
					{
						row.add(slotColumn.get(tier));
					}
					if (!row.isEmpty())
					{
						rows.add(row);
					}
				}
			}
			if (!other.isEmpty())
			{
				rows.add(other);
			}
			return rows;
		}

		List<T> tail = new ArrayList<>();
		for (int tier = 0; tier < tiers; tier++)
		{
			List<T> row = new ArrayList<>();
			for (EquipmentInventorySlot slot : ROW_ORDER)
			{
				List<T> slotColumn = grid.get(slot.getSlotIdx());
				if (slotColumn != null && tier < slotColumn.size() && slotColumn.get(tier) != null)
				{
					row.add(slotColumn.get(tier));
				}
			}
			if (tail.isEmpty() && row.size() >= MIN_ROW_ITEMS)
			{
				rows.add(row);
			}
			else
			{
				tail.addAll(row);
			}
		}
		tail.addAll(other);
		if (!tail.isEmpty())
		{
			rows.add(tail);
		}
		return rows;
	}

	/**
	 * Gives every piece a tier (outfit index). Pieces are ranked within their slot, except that two or more
	 * owned pieces of a set (by {@code set}) share one tier: that of the set's best piece. A set wins ties
	 * with single pieces, since set pieces are only strong together.
	 *
	 * @param bySlot items per slot, best first
	 * @return per slot, the item at each tier; null where that outfit has nothing for the slot
	 */
	private static <T> Map<Integer, List<T>> assignTiers(Map<Integer, List<T>> bySlot, EquipmentInventorySlot[] order,
		Function<T, String> set)
	{
		final class Unit
		{
			final Map<Integer, T> pieces = new LinkedHashMap<>();
			int rank = Integer.MAX_VALUE;
		}

		Map<String, Unit> sets = new LinkedHashMap<>();
		List<Unit> units = new ArrayList<>();
		for (EquipmentInventorySlot slot : order)
		{
			List<T> slotItems = bySlot.getOrDefault(slot.getSlotIdx(), Collections.emptyList());
			for (int rank = 0; rank < slotItems.size(); rank++)
			{
				T item = slotItems.get(rank);
				String setName = set.apply(item);
				Unit unit = setName == null ? null : sets.computeIfAbsent(setName, k -> new Unit());
				// A second piece for a slot the set already fills (e.g. another void helm) stands alone.
				if (unit == null || unit.pieces.containsKey(slot.getSlotIdx()))
				{
					unit = new Unit();
					units.add(unit);
				}
				unit.pieces.put(slot.getSlotIdx(), item);
				unit.rank = Math.min(unit.rank, rank);
			}
		}
		units.addAll(sets.values());
		units.sort(Comparator.comparingInt((Unit u) -> u.rank).thenComparing(u -> u.pieces.size() < 2));

		Map<Integer, List<T>> grid = new HashMap<>();
		for (Unit unit : units)
		{
			int tier = 0;
			while (occupied(grid, unit.pieces.keySet(), tier))
			{
				tier++;
			}
			for (Map.Entry<Integer, T> piece : unit.pieces.entrySet())
			{
				List<T> slotColumn = grid.computeIfAbsent(piece.getKey(), k -> new ArrayList<>());
				while (slotColumn.size() <= tier)
				{
					slotColumn.add(null);
				}
				slotColumn.set(tier, piece.getValue());
			}
		}
		return grid;
	}

	private static <T> boolean occupied(Map<Integer, List<T>> grid, Iterable<Integer> slots, int tier)
	{
		for (int slot : slots)
		{
			List<T> slotColumn = grid.get(slot);
			if (slotColumn != null && tier < slotColumn.size() && slotColumn.get(tier) != null)
			{
				return true;
			}
		}
		return false;
	}

	private static boolean inOrder(EquipmentInventorySlot[] order, int slotIdx)
	{
		for (EquipmentInventorySlot slot : order)
		{
			if (slot.getSlotIdx() == slotIdx)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * How good a piece is for the given combat style. Damage bonuses dominate; defence breaks ties
	 * between pure-defence pieces (e.g. rune vs dragon platebody).
	 */
	static int score(String category, ItemEquipmentStats e)
	{
		if (e == null)
		{
			return 0;
		}
		// Scaled by 20 so small defence differences (lunar vs beacon ring) aren't lost to rounding:
		// offence + prayer + average defence / 4.
		int defenceSum = e.getDstab() + e.getDslash() + e.getDcrush() + e.getDmagic() + e.getDrange();
		int offence;
		switch (category)
		{
			case Categories.RANGED:
				offence = 60 * e.getRstr() + 20 * e.getArange();
				break;
			case Categories.MAGIC:
				offence = Math.round(60 * e.getMdmg()) + 20 * e.getAmagic();
				break;
			default:
				offence = 60 * e.getStr() + 20 * Math.max(e.getAstab(), Math.max(e.getAslash(), e.getAcrush()));
		}
		return offence + 20 * e.getPrayer() + defenceSum;
	}

	/**
	 * Offensive value for one style only; zero or less means the piece does nothing for that style.
	 */
	static int offence(String category, ItemEquipmentStats e)
	{
		switch (category)
		{
			case Categories.RANGED:
				return 3 * e.getRstr() + e.getArange();
			case Categories.MAGIC:
				return Math.round(3 * e.getMdmg()) + e.getAmagic();
			default:
				int attack = Math.max(e.getAstab(), Math.max(e.getAslash(), e.getAcrush()));
				return 3 * e.getStr() + attack;
		}
	}
}

package com.smartbanksorter;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemEquipmentStats;

class ItemCopies
{
	private final Function<Slot, ItemEquipmentStats> equipmentOf;
	// Spare empty-slot widgets the bank interface already has past the last item. Copies reuse these, like
	// core Bank Tags layouts do for duplicates: the game treats them as real bank slots, so it builds their
	// menus itself, and onMenuOptionClicked points the click at the real item's slot.
	private List<Widget> spares = new ArrayList<>();
	// Copy widget's child index -> the real item's bank slot index.
	private final Map<Integer, Integer> copyTargets = new HashMap<>();

	ItemCopies(Function<Slot, ItemEquipmentStats> equipmentOf)
	{
		this.equipmentOf = equipmentOf;
	}

	void setSpares(List<Widget> spares)
	{
		this.spares = spares;
	}

	void clearTargets()
	{
		copyTargets.clear();
	}

	void hideFrom(int from)
	{
		for (int i = from; i < spares.size(); i++)
		{
			spares.get(i).setHidden(true);
		}
	}

	void clear()
	{
		spares = new ArrayList<>();
		copyTargets.clear();
	}

	/**
	 * Points a click on a copy at the real item's bank slot, so the game withdraws the real item.
	 * Same as core Bank Tags' LayoutManager.onMenuOptionClicked for layout duplicates: only the slot index of
	 * the game's own menu action is changed; no menu entries are added.
	 */
	void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (event.getParam1() == InterfaceID.Bankmain.ITEMS)
		{
			Integer real = copyTargets.get(event.getParam0());
			if (real != null)
			{
				event.getMenuEntry().setParam0(real);
			}
		}
	}

	/**
	 * Gear useful to several styles (barrows gloves, fire cape) lives in one category. Show a faded copy in
	 * each other combat style where it beats everything that style already has in that slot.
	 */
	void addHybridCopies(Map<String, List<Slot>> groups)
	{
		for (String style : SmartBankSorterPlugin.GEAR_CATEGORIES)
		{
			List<Slot> styleSlots = groups.get(style);
			if (styleSlots == null)
			{
				continue;
			}

			Map<Integer, Integer> bestBySlot = new HashMap<>();
			for (Slot s : styleSlots)
			{
				ItemEquipmentStats e = equipmentOf.apply(s);
				if (e != null)
				{
					bestBySlot.merge(e.getSlot(), GearOrder.score(style, e), Math::max);
				}
			}

			Map<Integer, Slot> candidates = new HashMap<>();
			for (String other : SmartBankSorterPlugin.GEAR_CATEGORIES)
			{
				if (other.equals(style) || !groups.containsKey(other))
				{
					continue;
				}
				for (Slot s : groups.get(other))
				{
					ItemEquipmentStats e = equipmentOf.apply(s);
					boolean blessing = e != null && e.getSlot() == EquipmentInventorySlot.AMMO.getSlotIdx();
					if (s.copy || e == null || e.getSlot() == EquipmentInventorySlot.WEAPON.getSlotIdx()
						|| (!blessing && GearOrder.offence(style, e) <= 0))
					{
						continue;
					}
					int score = GearOrder.score(style, e);
					Slot current = candidates.get(e.getSlot());
					if (score > bestBySlot.getOrDefault(e.getSlot(), 0)
						&& (current == null || score > GearOrder.score(style, equipmentOf.apply(current))))
					{
						candidates.put(e.getSlot(), s);
					}
				}
			}
			for (Slot s : candidates.values())
			{
				styleSlots.add(new Slot(s.widget, s.index, s.itemId, s.quantity, s.name, style, true));
			}
		}
	}

	/**
	 * Items the bundled data lists under extra categories (logs for Firemaking, Graceful for Farming...) get a
	 * withdrawable copy in each of them.
	 */
	void addDataCopies(Map<String, List<Slot>> groups)
	{
		List<Slot> originals = new ArrayList<>();
		groups.values().forEach(list -> list.stream().filter(s -> !s.copy).forEach(originals::add));
		for (Slot s : originals)
		{
			ItemData.Entry data = ItemData.get(s.name);
			if (data == null || !data.category.equals(s.category))
			{
				// A user rule moved it; their placement wins.
				continue;
			}
			for (String extra : data.extras)
			{
				List<Slot> target = groups.computeIfAbsent(extra, k -> new ArrayList<>());
				if (target.stream().noneMatch(t -> t.itemId == s.itemId))
				{
					target.add(new Slot(s.widget, s.index, s.itemId, s.quantity, s.name, extra, true));
				}
			}
		}
	}

	/**
	 * Teleport items that are also combat gear (charged glory, combat bracelet, max cape...) get a copy in
	 * their combat style, where the outfit columns rank them by stats. Only the most-charged version of each
	 * item is copied, so five glories don't fill the amulet row.
	 */
	void addTeleportGearCopies(Map<String, List<Slot>> groups)
	{
		List<Slot> teleports = groups.get(Categories.TELEPORTS);
		if (teleports == null)
		{
			return;
		}

		Map<String, Slot> best = new HashMap<>();
		for (Slot s : teleports)
		{
			ItemEquipmentStats e = equipmentOf.apply(s);
			if (s.copy || e == null || e.getSlot() == EquipmentInventorySlot.WEAPON.getSlotIdx())
			{
				continue;
			}
			best.merge(SmartBankSorterPlugin.baseName(s.name).toLowerCase(), s, (a, b) -> SmartBankSorterPlugin.dose(a.name) >= SmartBankSorterPlugin.dose(b.name) ? a : b);
		}
		for (Slot s : best.values())
		{
			ItemEquipmentStats e = equipmentOf.apply(s);
			String style = Categoriser.gear(s.name.toLowerCase(), e);
			if (SmartBankSorterPlugin.GEAR_CATEGORIES.contains(style) && GearOrder.offence(style, e) > 0)
			{
				List<Slot> target = groups.computeIfAbsent(style, k -> new ArrayList<>());
				if (target.stream().noneMatch(t -> t.itemId == s.itemId))
				{
					target.add(new Slot(s.widget, s.index, s.itemId, s.quantity, s.name, style, true));
				}
			}
		}
	}

	/**
	 * Draws a copy of {@code slot}'s item in the next spare slot widget, showing the real item's icon and
	 * quantity and carrying its options.
	 *
	 * @return the copy widget, or null when the bank has no spare slots left
	 */
	Widget placeCopy(Widget container, int index, Slot slot)
	{
		if (index >= spares.size())
		{
			return null;
		}
		Widget real = slot.widget;
		Widget w = spares.get(index);
		w.setItemId(real.getItemId());
		w.setItemQuantity(real.getItemQuantity());
		w.setItemQuantityMode(real.getItemQuantityMode());
		w.setOpacity(real.getOpacity());
		// Item outline and drop shadow, so the copy is drawn exactly like the real item.
		w.setBorderType(real.getBorderType());
		w.setTextShadowed(real.getTextShadowed());
		w.setName(real.getName());
		String[] actions = real.getActions();
		for (int i = 0; i < 10; i++)
		{
			w.setAction(i, actions != null && i < actions.length ? actions[i] : null);
		}
		w.setDragDeadZone(Integer.MAX_VALUE);
		w.setDragDeadTime(Integer.MAX_VALUE);
		w.setHidden(false);
		copyTargets.put(w.getIndex(), slot.index);
		return w;
	}
}

package com.smartbanksorter;

import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Bundled per-item data, classified from the OSRS Wiki. One line per item:
 * {@code Item name|Main category|Extra categories, comma separated|Tier 1-5}. Extra categories get
 * withdrawable copies of the item; tier orders items within a category (1 = most used).
 */
final class ItemData
{
	static final int UNKNOWN_TIER = 6;

	static final class Entry
	{
		final String category;
		final List<String> extras;
		final int tier;

		Entry(String category, List<String> extras, int tier)
		{
			this.category = category;
			this.extras = extras;
			this.tier = tier;
		}
	}

	private static final Map<String, Entry> ITEMS = parse(readResource("items.txt"));

	private ItemData()
	{
	}

	// Trailing variant markers: "(4)", "(i)", "(uncharged)", or a Barrows degrade level like " 75".
	private static final Pattern VARIANT = Pattern.compile("(\\s*\\([^()]*\\)|\\s+\\d+)$");

	/**
	 * Entry for this exact name, else for the name with variant suffixes stripped one at a time, so
	 * "Dharok's helm 75" and "Amulet of glory(4)" find "Dharok's helm" and "Amulet of glory".
	 */
	static Entry get(String name)
	{
		String n = name.toLowerCase().trim();
		while (true)
		{
			Entry e = ITEMS.get(n);
			if (e != null)
			{
				return e;
			}
			Matcher m = VARIANT.matcher(n);
			if (!m.find() || m.start() == 0)
			{
				return null;
			}
			n = n.substring(0, m.start()).trim();
		}
	}

	static int tier(String name)
	{
		Entry e = get(name);
		return e == null ? UNKNOWN_TIER : e.tier;
	}

	static Map<String, Entry> parse(String text)
	{
		Map<String, Entry> items = new HashMap<>();
		for (String line : text.split("\\R"))
		{
			String[] parts = line.split("\\|", -1);
			if (line.startsWith("#") || parts.length < 2 || parts[0].trim().isEmpty() || parts[1].trim().isEmpty())
			{
				continue;
			}

			List<String> extras = new ArrayList<>();
			if (parts.length > 2)
			{
				for (String extra : parts[2].split(","))
				{
					if (!extra.trim().isEmpty() && !extra.trim().equals(parts[1].trim()))
					{
						extras.add(extra.trim());
					}
				}
			}
			int tier = UNKNOWN_TIER;
			if (parts.length > 3)
			{
				try
				{
					tier = Integer.parseInt(parts[3].trim());
				}
				catch (NumberFormatException ignored)
				{
					// Leave as unknown.
				}
			}
			items.put(parts[0].trim().toLowerCase(), new Entry(parts[1].trim(), Collections.unmodifiableList(extras), tier));
		}
		return items;
	}

	private static String readResource(String name)
	{
		try (InputStream in = ItemData.class.getResourceAsStream(name))
		{
			return in == null ? "" : new String(in.readAllBytes(), StandardCharsets.UTF_8);
		}
		catch (IOException e)
		{
			return "";
		}
	}
}

package com.smartbanksorter;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.function.Supplier;
import java.util.regex.Matcher;
import net.runelite.api.Client;
import net.runelite.api.Menu;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.ColorUtil;

class MoveToMenu
{
	private final Client client;
	private final SmartBankSorterConfig config;
	private final ConfigManager configManager;
	private final ItemManager itemManager;
	private final Supplier<List<String>> categoryOrder;

	MoveToMenu(Client client, SmartBankSorterConfig config, ConfigManager configManager, ItemManager itemManager,
		Supplier<List<String>> categoryOrder)
	{
		this.client = client;
		this.config = config;
		this.configManager = configManager;
		this.itemManager = itemManager;
		this.categoryOrder = categoryOrder;
	}

	/**
	 * "Move to" sub-menu on bank items. Picking a category writes a rule to the Custom categories setting, so
	 * one-off fixes don't need a plugin change. Doses and charges are covered by one rule.
	 */
	void addMenu(int itemId)
	{
		String name = itemManager.getItemComposition(itemManager.canonicalize(itemId)).getName();
		String pattern = movePattern(name);
		boolean hasRule = findRule(pattern) >= 0;

		MenuEntry parent = client.getMenu().createMenuEntry(1)
			.setOption("Move to")
			.setTarget(ColorUtil.wrapWithColorTag(name, config.headerColor()))
			.setType(MenuAction.RUNELITE);
		Menu sub = parent.createSubMenu();
		List<String> targets = new ArrayList<>(categoryOrder.get());
		Collections.reverse(targets);
		for (String category : targets)
		{
			sub.createMenuEntry(-1)
				.setOption(category)
				.setType(MenuAction.RUNELITE)
				.onClick(e -> setRule(pattern, category));
		}
		if (hasRule)
		{
			sub.createMenuEntry(-1)
				.setOption("Reset")
				.setTarget(ColorUtil.wrapWithColorTag("automatic", config.headerColor()))
				.setType(MenuAction.RUNELITE)
				.onClick(e -> setRule(pattern, null));
		}
	}

	// "Prayer potion(4)" -> "Prayer potion(*"; other names match exactly.
	private static String movePattern(String name)
	{
		Matcher m = SmartBankSorterPlugin.DOSE.matcher(name);
		return m.matches() ? m.group(1) + "(*" : name;
	}

	/**
	 * Line index of the "Category: pattern" rule written for this exact pattern, or -1.
	 */
	private int findRule(String pattern)
	{
		String[] lines = config.customRules().split("\\R", -1);
		for (int i = 0; i < lines.length; i++)
		{
			int colon = lines[i].indexOf(':');
			if (colon > 0 && lines[i].substring(colon + 1).trim().equalsIgnoreCase(pattern))
			{
				return i;
			}
		}
		return -1;
	}

	/**
	 * Replaces this item's rule with one for {@code category}, or removes it when null. New rules go first so
	 * they win over broader lines the user wrote.
	 */
	private void setRule(String pattern, String category)
	{
		List<String> lines = new ArrayList<>(Arrays.asList(config.customRules().split("\\R", -1)));
		int existing = findRule(pattern);
		if (existing >= 0)
		{
			lines.remove(existing);
		}
		if (category != null)
		{
			lines.add(0, category + ": " + pattern);
		}
		lines.removeIf(String::isEmpty);
		configManager.setConfiguration(SmartBankSorterConfig.GROUP, "customRules", String.join("\n", lines));
	}
}

package com.smartbanksorter;

import net.runelite.api.widgets.Widget;

final class Slot
{
	final Widget widget;
	final int index;
	final int itemId;
	final int quantity;
	final String name;
	final String category;
	final boolean copy;

	Slot(Widget widget, int index, int itemId, int quantity, String name, String category)
	{
		this(widget, index, itemId, quantity, name, category, false);
	}

	Slot(Widget widget, int index, int itemId, int quantity, String name, String category, boolean copy)
	{
		this.copy = copy;
		this.widget = widget;
		this.index = index;
		this.itemId = itemId;
		this.quantity = quantity;
		this.name = name;
		this.category = category;
	}
}

package com.smartbanksorter;

