		keyName = "outfitLayout",
		name = "Outfit layout",
		description = "With 'Rank combat gear': Columns puts each outfit in a column read head to feet, best outfit"
			+ " leftmost. Rows puts each outfit on its own row, best on top.",
		position = -1,
		section = layoutSection
	)
