		return OutfitLayout.COLUMNS;
	}

	@ConfigItem(
		keyName = "headerSize",
		name = "Header size",
		description = "Small headers fit more items on screen in fixed (classic) mode",
		position = 0,
		section = layoutSection
	)
	default HeaderSize headerSize()
	{
		return HeaderSize.SMALL;
